import React, { useEffect, useState } from "react";
import MasonryContainer from "../Components/MasonryContainer";
import SentenceArray from "../Asset/Data/SentenceArray";
import CardSentence from "../Components/CardSentence";
import ContentsTab from "../Components/ContentsTab";
import MusicArray from "../Asset/Data/MusicArray";
import CardMusic from "../Components/CardMusic";
import BookArray from "../Asset/Data/BookArray";
import CardBook from "../Components/CardBook";
import { useNavigate } from "react-router-dom";

const Library = ({ currentTab }) => {
  const [contentsArray, setContentsArray] = useState({
    sentence: null,
    book: null,
    music: null,
  });
  const navigate = useNavigate();
  const tabArray = [
    { title: "문장", key: "sentence" },
    { title: "도서", key: "book" },
    { title: "음악", key: "music" },
  ];

  const shuffleContents = () => {
    let array;
    if (currentTab === "sentence") {
      array = SentenceArray;
    } else if (currentTab === "book") {
      array = BookArray;
    } else {
      array = MusicArray;
    }

    for (let index = array.length - 1; index > 0; index--) {
      const randomPosition = Math.floor(Math.random() * (index + 1));
      const temporary = array[index];
      array[index] = array[randomPosition];
      array[randomPosition] = temporary;
      const shuffled = array;
      if (index === 1) {
        if (currentTab === "sentence") {
          setContentsArray({ sentence: null, book: null, sentence: shuffled });
        } else if (currentTab === "book") {
          setContentsArray({ sentence: null, music: null, book: shuffled });
        } else {
          setContentsArray({ sentence: null, book: null, music: shuffled });
        }
      }
    }
  };

  useEffect(() => {
    shuffleContents();
  }, [currentTab]);

  const setCurrentTab = (tab) => {
    navigate(tab);
  };

  return (
    <>
      <ContentsTab
        tabArray={tabArray}
        setCurrentTab={setCurrentTab}
        currentTab={currentTab}
      ></ContentsTab>
      <MasonryContainer>
        {currentTab === "sentence"
          ? contentsArray["sentence"]?.map((sentence, index) => (
              <CardSentence
                key={index}
                sentence={sentence.sentence}
                tags={sentence.tags}
                originType={sentence.origin.type}
                originName={sentence.origin.name}
                originUrl={sentence.origin.url}
              ></CardSentence>
            ))
          : currentTab === "book"
          ? contentsArray["book"]?.map((book, index) => (
              <CardBook
                key={index}
                bookCover={book.bookCover}
                title={book.title}
                author={book.author}
                sentence={book.sentence}
                url={book.url}
                tags={book.tags}
              ></CardBook>
            ))
          : contentsArray["music"]?.map((music, index) => (
              <CardMusic
                key={index}
                albumArt={music.albumArt}
                title={music.title}
                artist={music.artist}
                playtime={music.playtime}
                playlist={music.playlist}
              ></CardMusic>
            ))}
      </MasonryContainer>
    </>
  );
};

export default Library;
